import React, { useState } from 'react';
import { FiFilter } from 'react-icons/fi';
import { HiOutlineSortAscending } from 'react-icons/hi';
import Navbar from '../../components/Navbar';
import DatasetTable from './DatasetTable';
import ExploreSidebar from './ExploreSidebar';
import '../../styles/tokens.css';

export default function DatasetExplorerPage() {
  const [filters, setFilters] = useState({});
  const [datasets] = useState(Array(7).fill({}));

  return (
    <>
      <Navbar />
      <div className="flex min-h-screen h-screen page-bg">
        <ExploreSidebar filters={filters} setFilters={setFilters} />

        <main className="flex-1 p-6">
          {/* Header */}
          <div className="flex justify-between items-center mb-4">
            <h1 className="text-2xl font-bold text-textPrimary-light dark:text-textPrimary-dark">Datasets</h1>
            <div className="flex gap-2">
              <button className="btn-outline flex items-center gap-1"><FiFilter /> Filter</button>
              <button className="btn-outline flex items-center gap-1"><HiOutlineSortAscending /> Sort</button>
              <button className="btn-accent">+ Request Dataset</button>
            </div>
          </div>

          {/* Metrics */}
          <div className="grid grid-cols-4 gap-4 mb-6">
            {[
              ['Total Datasets', 128],
              ['Pinned Datasets', 7],
              ['Recently Updated', 23],
              ['Total Variables', '4,582']
            ].map(([label, value]) => (
              <div
                key={label}
                className="p-4 rounded-lg bg-white dark:bg-gray-850 border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-gray-200 shadow-sm"
              >
                <p className="text-sm">{label}</p>
                <span className="font-bold text-xl">{value}</span>
              </div>
            ))}
          </div>

          {/* Dataset Table */}
          <DatasetTable datasets={datasets} />

          {/* Pagination */}
          <div className="flex justify-end mt-4 gap-1">
            {[1, 2, 3, 4, 5].map(page => (
              <button
                key={page}
                className="px-3 py-1 rounded border border-default text-sm bg-card-light dark:bg-card-dark text-textPrimary-light dark:text-textPrimary-dark"
              >
                {page}
              </button>
            ))}
          </div>
        </main>
      </div>
    </>
  );
}
